// LC 415：从低位向高位逐位相加，个位先进入 StringBuilder，返回前反转。
// 换题：减法把 carry 改成借位，当前差 < 0 时加 10 并向高位借 1；基数不是 10 时替换下面的 10。
static String addStrings(String num1, String num2) {
    int i = num1.length() - 1;
    int j = num2.length() - 1;
    int carry = 0;
    StringBuilder sb = new StringBuilder();
    while (i >= 0 || j >= 0 || carry > 0) {
        int d1 = 0;
        int d2 = 0;
        if (i >= 0) {
            d1 = num1.charAt(i) - '0';
            i--;
        }
        if (j >= 0) {
            d2 = num2.charAt(j) - '0';
            j--;
        }
        int sum = d1 + d2 + carry;
        sb.append((char) ('0' + sum % 10));
        carry = sum / 10;
    }
    return sb.reverse().toString();
}
// LC 43：num1[i] * num2[j] 累加到 acc[i + j + 1]，再从低位向高位一次进位。
// 无前导零时只有全 0 需要特判；若存在前导零，先剥掉再判断是否为 0。
// 换题：大数除法改为从高位试商，余数 * 基数后加下一位。
static String multiply(String num1, String num2) {
    if (num1.equals("0") || num2.equals("0")) {
        return "0";
    }
    int m = num1.length();
    int n = num2.length();
    int[] acc = new int[m + n];
    for (int i = m - 1;
    i >= 0;
    i--) {
        int d1 = num1.charAt(i) - '0';
        for (int j = n - 1;
        j >= 0;
        j--) {
            acc[i + j + 1] += d1 * (num2.charAt(j) - '0');
        }
    }
    for (int k = m + n - 1;
    k > 0;
    k--) {
        acc[k - 1] += acc[k] / 10;
        acc[k] %= 10;
    }
    StringBuilder sb = new StringBuilder();
    int start = acc[0] == 0 ? 1 : 0;
    for (int k = start;
    k < acc.length;
    k++) {
        sb.append((char) ('0' + acc[k]));
    }
    return sb.toString();
}

// LC 54。top/bottom/left/right 是还没输出的边界，每走完一条边立刻收缩。
// 单行或单列时，收缩后必须再用 top<=bottom、left<=right 判断，否则回程会重复或越界。
// 换题：逆时针改成上行、左列、下行、右列。对角线遍历不要复用这四条边，改按 d=row+col 分组。
static List<Integer> spiralOrder(int[][] matrix) {
    List<Integer> ans = new ArrayList<>();
    if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
        return ans;
    }
    int top = 0;
    int bottom = matrix.length - 1;
    int left = 0;
    int right = matrix[0].length - 1;
    while (top <= bottom && left <= right) {
        for (int c = left;
        c <= right;
        c++) {
            ans.add(matrix[top][c]);
        }
        top++;
        for (int r = top;
        r <= bottom;
        r++) {
            ans.add(matrix[r][right]);
        }
        right--;
        if (top <= bottom) {
            for (int c = right;
            c >= left;
            c--) {
                ans.add(matrix[bottom][c]);
            }
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom;
            r >= top;
            r--) {
                ans.add(matrix[r][left]);
            }
            left++;
        }
    }
    return ans;
}

// 反转闭区间 [l, r]。l>=r 时直接返回，空区间不会越界。
static void reverseRange(int[] a, int l, int r) {
    while (l < r) {
        int t = a[l];
        a[l] = a[r];
        a[r] = t;
        l++;
        r--;
    }
}
// LC 189 右旋 k：整体反转，再反转前 k 个，再反转剩余部分。
// k 先规范到 [0, n)。Java 中负 k 取模仍为负，所以写成 (k % n + n) % n；左旋 k 等价于右旋 n-k。
// 换题：LC 48 先按主对角线转置，再对每一行调用 reverseRange(row, 0, n-1)，得到顺时针 90°。
static void rotate(int[] nums, int k) {
    int n = nums.length;
    if (n == 0) {
        return;
    }
    k = (k % n + n) % n;
    reverseRange(nums, 0, n - 1);
    reverseRange(nums, 0, k - 1);
    reverseRange(nums, k, n - 1);
}

